import{_ as t,c as a,o,ag as i}from"./chunks/framework.ARG558ZT.js";const h=JSON.parse('{"title":"A07 — Custom VPC and connectivity","description":"","frontmatter":{},"headers":[],"relativePath":"practice/aws/associate-07.md","filePath":"practice/aws/associate-07.md"}'),n={name:"practice/aws/associate-07.md"};function r(d,e,s,l,c,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="a07-—-custom-vpc-and-connectivity" tabindex="-1">A07 — Custom VPC and connectivity <a class="header-anchor" href="#a07-—-custom-vpc-and-connectivity" aria-label="Permalink to “A07 — Custom VPC and connectivity”">​</a></h1><p><strong>Learner status: not started. All supplied tasks on this page are mandatory in this learning path</strong>, including items originally labelled optional or bonus. Repeating tasks still require the stated action or comparison; reuse earlier resources and code where suitable, and record the new evidence. Source optional labels describe the original course only.</p><p><strong>Read first:</strong> <a href="./../../aws/networking.html">networking</a>.</p><h2 id="a07-1-—-required-network-layout" tabindex="-1">A07.1 — Required network layout <a class="header-anchor" href="#a07-1-—-required-network-layout" aria-label="Permalink to “A07.1 — Required network layout”">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>Required name / address</th></tr></thead><tbody><tr><td>VPC</td><td><code>CloudX-VPC</code>, <code>10.0.0.0/16</code></td></tr><tr><td>Internet gateway</td><td><code>CloudX-IGW</code>, attached to the VPC</td></tr><tr><td>Public subnet A</td><td><code>CloudX-PublicSubnet-A</code>, AZ A, <code>10.0.10.0/24</code></td></tr><tr><td>Public subnet B</td><td><code>CloudX-PublicSubnet-B</code>, AZ B, <code>10.0.20.0/24</code></td></tr><tr><td>Public route table</td><td><code>CloudX-Public-RT</code>, local route and <code>0.0.0.0/0</code> → internet gateway</td></tr><tr><td>Private subnet A</td><td><code>CloudX-PrivateSubnet-A</code>, AZ A, <code>10.0.11.0/24</code></td></tr><tr><td>Private route table</td><td><code>CloudX-Private-RT-A</code>, local route and default route → NAT</td></tr><tr><td>DB subnet A</td><td><code>CloudX-DbSubnet-A</code>, AZ A, <code>10.0.13.0/24</code></td></tr><tr><td>DB route table</td><td><code>CloudX-Db-RT-A</code>, local route only</td></tr><tr><td>NAT gateway</td><td><code>CloudX-Nat-GW-A</code>, public subnet A, allocated Elastic IP</td></tr></tbody></table><ul><li>[ ] Create these resources and explicit subnet/route-table associations. Configure public address assignment as required; the internet-gateway route is what makes the public subnet&#39;s routing public.</li><li>[ ] Place a bastion in public subnet B with SSH only from your IP. Adapt the earlier EC2 CloudFormation template.</li><li>[ ] Deploy a static web application on an instance in public subnet A, with public HTTP/HTTPS permission.</li><li>[ ] Create one instance in the private subnet and one in the DB subnet. Apply the source&#39;s shared, self-referencing security group to the intended instances. Keep that broad internal group identified as a lab topology.</li><li>[ ] Verify public website access, bastion-mediated private/DB access, public/bastion outbound internet access, private outbound internet through NAT, public/private access to the DB instance, and absence of DB internet access. Distinguish routing restrictions from OS/firewall responses; failed ping alone is not a full connectivity diagnosis.</li></ul><h2 id="a07-2-—-rebuild-through-cloudformation-—-promoted-from-optional-repeating-a07-1-a06" tabindex="-1">A07.2 — Rebuild through CloudFormation — promoted from optional; repeating A07.1/A06 <a class="header-anchor" href="#a07-2-—-rebuild-through-cloudformation-—-promoted-from-optional-repeating-a07-1-a06" aria-label="Permalink to “A07.2 — Rebuild through CloudFormation — promoted from optional; repeating A07.1/A06”">​</a></h2><ul><li>[ ] Define the same VPC topology in CloudFormation, create the stack, inspect resources, compare against the manual topology and destroy the disposable stack after verification.</li></ul><h2 id="a07-3-—-guide-bonuses-endpoints-flow-logs-and-cleanup-—-mandatory" tabindex="-1">A07.3 — Guide bonuses: endpoints, flow logs and cleanup — mandatory <a class="header-anchor" href="#a07-3-—-guide-bonuses-endpoints-flow-logs-and-cleanup-—-mandatory" aria-label="Permalink to “A07.3 — Guide bonuses: endpoints, flow logs and cleanup — mandatory”">​</a></h2><ul><li>[ ] Configure the supplied guide&#39;s S3 VPC endpoint scenario and demonstrate the private service path with appropriate routes and permissions.</li><li>[ ] Configure a VPC flow log and inspect accepted/rejected traffic metadata in the selected destination. Configure the needed publishing permissions; do not interpret flow logs as HTTP payload logs.</li><li>[ ] Stop unused instances, delete unused NAT gateways and release their addresses. Inspect and remove/update stale routes rather than leaving them as an unexplained final state.</li></ul><p><strong>Repeating:</strong> EC2, SSH, security groups and web hosting repeat A03; automation repeats A06. This lab&#39;s new evidence is the traffic-path matrix across public, private and isolated subnets.</p><h2 id="completion-evidence" tabindex="-1">Completion evidence <a class="header-anchor" href="#completion-evidence" aria-label="Permalink to “Completion evidence”">​</a></h2><ul><li>[ ] Record observed results for every section, including all promoted extensions.</li><li>[ ] Retain configuration/code, successful and denied/failing cases where specified, and actual cleanup state.</li><li>[ ] Link earlier evidence for repeating work and add the new interface/behavior comparison.</li></ul><p>Use the <a href="./#evidence-for-every-required-module">shared evidence rules</a>; never claim screenshots or sample code complete independent work.</p>',14)])])}const b=t(n,[["render",r]]);export{h as __pageData,b as default};
